BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE SCHEMA IF NOT EXISTS app;
CREATE TYPE app.user_status AS ENUM('ACTIVE','LOCKED','INACTIVE');
CREATE TYPE app.role_code AS ENUM('FIELD','OFFICE','ADMIN','AUDITOR');
CREATE TYPE app.record_status AS ENUM('DRAFT','CONFIRMED','SUBMITTED','APPROVED','REJECTED','REVOKED','BILLING_LOCKED');
CREATE TYPE app.settlement_type AS ENUM('QUANTITY','TIME');
CREATE TYPE app.transport_type AS ENUM('ALLOCATED','PER_TRIP','MONTHLY_FIXED','NONE');
CREATE TYPE app.billing_status AS ENUM('OPEN','CALCULATING','CALCULATED','NEEDS_REVIEW','REVIEWED','FINALIZED','ISSUED','SENT','VOIDED');
CREATE TYPE app.job_status AS ENUM('QUEUED','PROCESSING','GENERATED','SENDING','SENT','FAILED_RETRYABLE','FAILED_FINAL');
CREATE TABLE app.users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),login_id varchar(100) NOT NULL UNIQUE,password_hash text NOT NULL,display_name varchar(100) NOT NULL,status app.user_status NOT NULL DEFAULT 'ACTIVE',failed_attempts int NOT NULL DEFAULT 0 CHECK(failed_attempts>=0),locked_until timestamptz,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.user_roles(user_id uuid NOT NULL REFERENCES app.users(id),role app.role_code NOT NULL,PRIMARY KEY(user_id,role));
CREATE TABLE app.customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(30) NOT NULL UNIQUE,name varchar(200) NOT NULL,closing_day smallint NOT NULL DEFAULT 31 CHECK(closing_day BETWEEN 1 AND 31),active boolean NOT NULL DEFAULT true,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.customer_contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES app.customers(id),code varchar(30) NOT NULL,name varchar(100) NOT NULL,email varchar(320) NOT NULL,send_daily boolean NOT NULL DEFAULT false,send_invoice boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,UNIQUE(customer_id,code));
CREATE TABLE app.workers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(30) NOT NULL UNIQUE,name varchar(100) NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE app.products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES app.customers(id),code varchar(80) NOT NULL,name varchar(200) NOT NULL,settlement_type app.settlement_type NOT NULL,lot_required boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,UNIQUE(customer_id,code));
CREATE TABLE app.product_contacts(product_id uuid NOT NULL REFERENCES app.products(id),contact_id uuid NOT NULL REFERENCES app.customer_contacts(id),purpose varchar(20) NOT NULL CHECK(purpose IN('DAILY','INVOICE')),PRIMARY KEY(product_id,contact_id,purpose));
CREATE TABLE app.work_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES app.products(id),code varchar(50) NOT NULL,name varchar(200) NOT NULL,active boolean NOT NULL DEFAULT true,UNIQUE(product_id,code));
CREATE TABLE app.defect_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES app.products(id),code varchar(50) NOT NULL,name varchar(100) NOT NULL,sort_order int NOT NULL DEFAULT 0,active boolean NOT NULL DEFAULT true,UNIQUE(product_id,code));
CREATE TABLE app.holidays(holiday_date date PRIMARY KEY,name varchar(100) NOT NULL);
CREATE TABLE app.rate_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES app.products(id),work_type_id uuid REFERENCES app.work_types(id),unit_price numeric(18,4) NOT NULL CHECK(unit_price>=0),overtime_multiplier numeric(8,4) NOT NULL DEFAULT 1.25 CHECK(overtime_multiplier>=1),valid_from date NOT NULL,valid_to date,CHECK(valid_to IS NULL OR valid_to>=valid_from));
ALTER TABLE app.rate_rules ADD CONSTRAINT rate_no_overlap EXCLUDE USING gist(product_id WITH =,(COALESCE(work_type_id,'00000000-0000-0000-0000-000000000000'::uuid)) WITH =,(daterange(valid_from,COALESCE(valid_to,'infinity'::date),'[]')) WITH &&);
CREATE TABLE app.transport_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES app.products(id),work_type_id uuid REFERENCES app.work_types(id),type app.transport_type NOT NULL,amount_yen bigint NOT NULL DEFAULT 0 CHECK(amount_yen>=0),allocation_group varchar(50),valid_from date NOT NULL,valid_to date,CHECK(valid_to IS NULL OR valid_to>=valid_from));
ALTER TABLE app.transport_rules ADD CONSTRAINT transport_no_overlap EXCLUDE USING gist(product_id WITH =,(COALESCE(work_type_id,'00000000-0000-0000-0000-000000000000'::uuid)) WITH =,type WITH =,(daterange(valid_from,COALESCE(valid_to,'infinity'::date),'[]')) WITH &&);
CREATE TABLE app.fixed_charge_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES app.products(id),label varchar(200) NOT NULL,amount_yen bigint NOT NULL CHECK(amount_yen>=0),valid_from date NOT NULL,valid_to date,CHECK(valid_to IS NULL OR valid_to>=valid_from));
CREATE TABLE app.work_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_no varchar(30) NOT NULL UNIQUE,current_revision_id uuid,status app.record_status NOT NULL DEFAULT 'DRAFT',owner_id uuid NOT NULL REFERENCES app.users(id),version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.work_report_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid NOT NULL REFERENCES app.work_reports(id),parent_revision_id uuid REFERENCES app.work_report_revisions(id),revision_no int NOT NULL,work_date date NOT NULL,reporter_id uuid NOT NULL REFERENCES app.users(id),customer_id uuid NOT NULL REFERENCES app.customers(id),product_id uuid NOT NULL REFERENCES app.products(id),work_type_id uuid NOT NULL REFERENCES app.work_types(id),lot_no varchar(100),start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,break_minutes int NOT NULL CHECK(break_minutes>=0),regular_minutes int NOT NULL CHECK(regular_minutes>=0),overtime_minutes int NOT NULL CHECK(overtime_minutes>=0),regular_person_minutes int NOT NULL CHECK(regular_person_minutes>=0),overtime_person_minutes int NOT NULL CHECK(overtime_person_minutes>=0),quantity int NOT NULL CHECK(quantity>=0),confirmed_at timestamptz,CHECK(end_at>start_at),UNIQUE(report_id,revision_no));
ALTER TABLE app.work_reports ADD CONSTRAINT work_current_revision_fk FOREIGN KEY(current_revision_id) REFERENCES app.work_report_revisions(id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE app.work_report_workers(revision_id uuid NOT NULL REFERENCES app.work_report_revisions(id),worker_id uuid NOT NULL REFERENCES app.workers(id),PRIMARY KEY(revision_id,worker_id));
CREATE TABLE app.defect_results(revision_id uuid NOT NULL REFERENCES app.work_report_revisions(id),defect_type_id uuid NOT NULL REFERENCES app.defect_types(id),quantity int NOT NULL CHECK(quantity>=0),PRIMARY KEY(revision_id,defect_type_id));
CREATE TABLE app.delivery_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_no varchar(30) NOT NULL UNIQUE,current_revision_id uuid,status app.record_status NOT NULL DEFAULT 'DRAFT',owner_id uuid NOT NULL REFERENCES app.users(id),version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.delivery_report_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid NOT NULL REFERENCES app.delivery_reports(id),parent_revision_id uuid REFERENCES app.delivery_report_revisions(id),revision_no int NOT NULL,delivery_date date NOT NULL,driver_id uuid NOT NULL REFERENCES app.workers(id),customer_id uuid NOT NULL REFERENCES app.customers(id),confirmed_at timestamptz,UNIQUE(report_id,revision_no));
ALTER TABLE app.delivery_reports ADD CONSTRAINT delivery_current_revision_fk FOREIGN KEY(current_revision_id) REFERENCES app.delivery_report_revisions(id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE app.delivery_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),delivery_revision_id uuid NOT NULL REFERENCES app.delivery_report_revisions(id),product_id uuid NOT NULL REFERENCES app.products(id),quantity int NOT NULL CHECK(quantity>0),allocation_eligible boolean NOT NULL DEFAULT false,UNIQUE(delivery_revision_id,product_id));
CREATE TABLE app.approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_type varchar(20) NOT NULL CHECK(entity_type IN('WORK','DELIVERY')),revision_id uuid NOT NULL,result varchar(20) NOT NULL CHECK(result IN('APPROVE','REJECT','REVOKE')),reason text,actor_id uuid NOT NULL REFERENCES app.users(id),acted_at timestamptz NOT NULL DEFAULT now(),CHECK(result='APPROVE' OR length(trim(reason))>0));
CREATE TABLE app.billing_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES app.customers(id),period_start date NOT NULL,period_end date NOT NULL,status app.billing_status NOT NULL DEFAULT 'OPEN',calc_version int NOT NULL DEFAULT 1,rule_hash char(64),version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),finalized_at timestamptz,UNIQUE(customer_id,period_start,period_end,calc_version));
CREATE TABLE app.billing_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),billing_run_id uuid NOT NULL REFERENCES app.billing_runs(id),source_type varchar(30) NOT NULL,source_revision_id uuid,line_type varchar(30) NOT NULL,description varchar(300) NOT NULL,raw_quantity numeric(18,4),unit varchar(20),unit_price numeric(18,4),multiplier numeric(8,4),unrounded_amount numeric(18,4) NOT NULL,amount_yen bigint NOT NULL,rule_snapshot jsonb NOT NULL,calculation jsonb NOT NULL);
CREATE TABLE app.invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),billing_run_id uuid NOT NULL REFERENCES app.billing_runs(id),invoice_no varchar(30) NOT NULL,revision int NOT NULL,status app.billing_status NOT NULL,customer_snapshot jsonb NOT NULL,subtotal_yen bigint NOT NULL,tax_yen bigint NOT NULL,total_yen bigint NOT NULL,tax_rate numeric(8,4) NOT NULL DEFAULT 0.10,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(invoice_no,revision));
CREATE TABLE app.invoice_recipients(invoice_id uuid NOT NULL REFERENCES app.invoices(id),email varchar(320) NOT NULL,recipient_type varchar(10) NOT NULL CHECK(recipient_type IN('TO','CC','BCC')),contact_snapshot jsonb NOT NULL,PRIMARY KEY(invoice_id,email,recipient_type));
CREATE TABLE app.files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),storage_key text NOT NULL UNIQUE,mime_type varchar(100) NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes>=0),sha256 char(64) NOT NULL,classification varchar(30) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.document_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_type varchar(30) NOT NULL,source_type varchar(30) NOT NULL,source_id uuid NOT NULL,template_version varchar(30) NOT NULL,status app.job_status NOT NULL DEFAULT 'QUEUED',idempotency_key varchar(300) NOT NULL UNIQUE,file_id uuid REFERENCES app.files(id),attempts int NOT NULL DEFAULT 0,error_code varchar(80),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.mail_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_job_id uuid NOT NULL REFERENCES app.document_jobs(id),recipients jsonb NOT NULL,subject varchar(200) NOT NULL,status app.job_status NOT NULL DEFAULT 'QUEUED',send_revision int NOT NULL DEFAULT 1,idempotency_key varchar(300) NOT NULL UNIQUE,provider_message_id varchar(300),attempts int NOT NULL DEFAULT 0,error_code varchar(80),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_type varchar(100) NOT NULL,aggregate_type varchar(50) NOT NULL,aggregate_id uuid NOT NULL,payload jsonb NOT NULL,status varchar(20) NOT NULL DEFAULT 'PENDING',attempts int NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.idempotency_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL REFERENCES app.users(id),route varchar(200) NOT NULL,idempotency_key varchar(100) NOT NULL,request_hash char(64) NOT NULL,response_status int,response_body jsonb,status varchar(20) NOT NULL CHECK(status IN('PROCESSING','COMPLETED','FAILED')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(actor_id,route,idempotency_key));
CREATE TABLE app.billing_warnings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),billing_run_id uuid NOT NULL REFERENCES app.billing_runs(id),code varchar(80) NOT NULL,source_type varchar(30),source_revision_id uuid,message varchar(500) NOT NULL,resolution varchar(30) CHECK(resolution IN('ACCEPT','EXCLUDE','CORRECT_SOURCE')),reason text,resolved_by uuid REFERENCES app.users(id),resolved_at timestamptz,CHECK((resolution IS NULL)=(resolved_at IS NULL)));
CREATE TABLE app.processed_events(consumer varchar(100) NOT NULL,event_id uuid NOT NULL,processed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(consumer,event_id));
CREATE TABLE app.template_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),template_type varchar(40) NOT NULL,version varchar(30) NOT NULL,provider_template_id text NOT NULL,sha256 char(64) NOT NULL,active_from timestamptz NOT NULL,retired_at timestamptz,UNIQUE(template_type,version));
CREATE TABLE app.audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES app.users(id),action varchar(80) NOT NULL,target_type varchar(50) NOT NULL,target_id uuid NOT NULL,before_data jsonb,after_data jsonb,reason text,correlation_id uuid NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX work_revision_search ON app.work_report_revisions(work_date,customer_id,product_id);
CREATE INDEX delivery_revision_search ON app.delivery_report_revisions(delivery_date,customer_id);
CREATE INDEX report_status ON app.work_reports(status,updated_at);
CREATE INDEX delivery_status ON app.delivery_reports(status,updated_at);
CREATE INDEX outbox_ready ON app.outbox_events(status,available_at);
CREATE INDEX idempotency_expiry ON app.idempotency_records(expires_at);
CREATE INDEX billing_warning_open ON app.billing_warnings(billing_run_id) WHERE resolved_at IS NULL;
CREATE INDEX audit_target ON app.audit_events(target_type,target_id,occurred_at DESC);
CREATE FUNCTION app.reject_immutable_revision_update() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'confirmed revision is immutable' USING ERRCODE='55000'; END$$;
CREATE TRIGGER work_revision_immutable BEFORE UPDATE OR DELETE ON app.work_report_revisions FOR EACH ROW WHEN (OLD.confirmed_at IS NOT NULL) EXECUTE FUNCTION app.reject_immutable_revision_update();
CREATE TRIGGER delivery_revision_immutable BEFORE UPDATE OR DELETE ON app.delivery_report_revisions FOR EACH ROW WHEN (OLD.confirmed_at IS NOT NULL) EXECUTE FUNCTION app.reject_immutable_revision_update();
CREATE FUNCTION app.reject_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'audit events are append-only' USING ERRCODE='55000'; END$$;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON app.audit_events FOR EACH ROW EXECUTE FUNCTION app.reject_audit_mutation();
COMMIT;
